//   5.4 Wallet Unit: sign SessionTranscript (deviceSignature)
//   5.5 Wallet Unit: encrypt the response
//   6 Wallet Unit → Verifier: POST response_uri (direct_post.jwt) → ResponsePost
//   7 Verifier: validate response
//   7.1 Verifier: decrypt JWE
//   7.2 Verifier: match state
//   7.3 Verifier: vp_token vs DCQL
//   7.4 Verifier: issuerAuth signature + x5chain
//   7.5 Verifier: data elements vs valueDigests
//   7.6 Verifier: deviceSignature over SessionTranscript
//   7.7 Verifier: validityInfo
//   7.8 Verifier: status (MSO)
//   8 Verifier → Wallet Unit: 200 redirect_uri → ResponseAck
//   9 Wallet Unit → Verifier: open redirect_uri
//   10 Verifier: frontend fetches result (response_code)

type bstr = string // CBOR byte string, shown as hex

// ── Verifier prepares the transaction and the signed Request Object ── Verifier → Verifier · step 1 in every flow

// ── Verifier generates a fresh nonce for the transaction ── Verifier → Verifier · step 1.1 in every flow
// rule: Verifier: MUST · "The Verifier MUST create a fresh, cryptographically random number with sufficient entropy for every Authorization Request, store it with its current session, and pass it in the nonce Authorization Request Parameter to the Wallet."

// ── Verifier generates an ephemeral response encryption key ── Verifier → Verifier · step 1.2 in every flow
// rule: Verifier: MUST · "Verifiers MUST supply ephemeral encryption public keys specific to each Authorization Request passed via client metadata as specified in Section 8.3 of [OIDF.OID4VP]." · "The JWE alg (algorithm) header parameter (see Section 4.1.1 of [RFC7516]) value ECDH-ES (as defined in Section 4.6 of [RFC7518]), with key agreement utilizing keys on the P-256 curve (see Section 6.2.1.1 of [RFC7518]) MUST be supported."

// ── Verifier signs the Request Object with the RP access certificate key ── Verifier → Verifier · step 1.3 in every flow
// rule: Verifier: MUST [R1]

// ── Authorization Request (wallet invocation) ── Verifier → Wallet Unit · steps redirect-same 2, redirect-same-mdoc 2
export interface AuthorizationRequest {
  query: {
    client_id: string // MUST · Verifier identifier; must match client_id inside the Request Object. [R2]
    request_uri: string // MUST · URL where the Wallet fetches the signed Request Object. [R3]
  }
}
// also:
//   - URL scheme that invokes the Wallet: Wallet: MUST · Custom URL scheme that makes the device open a Wallet with the presentation request. · "OIDFVP-HAIP-REDIRECTS-03: The EUDI Wallet shall support at least a custom URL scheme "eu-eaap://" for its authorization_endpoint."

// ── Request Object fetched from request_uri ── GET /request/{id} · Wallet Unit → Verifier · steps redirect-same 3, redirect-cross 3, redirect-same-mdoc 3
// rule: Wallet: MUST · "Upon receipt of the Request, the authorization server MUST send an HTTP "GET" request to the "request_uri" to retrieve the referenced Request Object"
export interface RequestUriFetch {
  headers: {
    Accept?: string // no rule · Media types the client is willing to receive in the response.
  }
}

// ── Request Object (JAR) ── Verifier → Wallet Unit · steps redirect-same 4, redirect-cross 4, redirect-same-mdoc 4
// Signed JWT carrying the Verifier's full presentation request: who asks, what for, and where to answer.
export interface RequestObjectMessage {
  headers: {
    "Content-Type"?: string // no rule · Media type of the HTTP body, e.g. application/json, application/x-www-form-urlencoded or application/jwt.
  }
  body: RequestObject
}
/** JWS, produced by Verifier. */
export type RequestObject = {
  header: {
    typ: "oauth-authz-req+jwt" // MUST; Wallet: MUST · Marks the JWT as a signed authorization request (oauth-authz-req+jwt). · "Verifiers MUST include the typ Header Parameter in Request Objects with the value oauth-authz-req+jwt, as defined in [RFC9101]." · "Wallets MUST NOT process Request Objects where the typ Header Parameter is not present or does not have the value oauth-authz-req+jwt."
    alg: string // MUST · Algorithm the JWS is signed with (or the JWE key is managed with), e.g. ES256. [R4]
    x5c: string[] // MUST · Certificate chain of the signing key, starting with the relying party's access certificate. [R1]
  }
  payload: {
    client_id: string // MUST · Verifier identifier; with the x509_hash prefix it is the hash of the leaf certificate in x5c. [R2]
    client_id_scheme?: string // only redirect-same, redirect-cross: Wallet: MUST · Pre-1.0 parameter naming the client identifier scheme; OpenID4VP 1.0 uses a prefix in client_id instead. · "The Wallet MUST ignore any unrecognized parameters, other than the transaction_data parameter."
    iss?: string // only redirect-same, redirect-cross: MAY; Wallet: MUST · Issuer of the Request Object; the Wallet relies on client_id instead. · "To avoid breaking existing JAR implementations, the iss claim MAY be present in the Request Object." · "However, if it is present, the Wallet MUST ignore it."
    response_type: string // MUST · What the Wallet returns; vp_token for a presentation. · "The Response type MUST be vp_token."
    response_mode: string // redirect-same, redirect-cross, redirect-same-mdoc: MUST | dc-api: MUST · How the response is delivered, e.g. direct_post.jwt (encrypted POST to response_uri) or dc_api.jwt. [R5] [R6]
    response_uri: string // except dc-api: MUST · URL where the Wallet posts the Authorization Response. · "response_uri: REQUIRED when the Response Mode direct_post is used. The URL to which the Wallet MUST send the Authorization Response using an HTTP POST request as defined by the Response Mode direct_post."
    nonce: string // MUST · Fresh random value from the Verifier; the Wallet signs it into the Key Binding JWT to prove freshness. · "nonce: REQUIRED. A case-sensitive String representing a value to securely bind Verifiable Presentation(s) provided by the Wallet to the particular transaction."
    state?: string // except dc-api: MAY · Value the Verifier uses to match the response to its transaction. [R7]
    aud: string // MUST · Audience of the Request Object; for a Wallet that is not known in advance this is https://self-issued.me/v2. · "OIDFVP-HAIP-COMMON-REQ-RO-22: The RO JWT body shall contain the aud parameter."
    iat?: number // MAY · Time the JWT was issued, in seconds since the epoch. [R8]
    exp?: number // MAY · Expiry time of the JWT, in seconds since the epoch; the JWT is not accepted after it. [R9]
    dcql_query: { // MUST; Wallet: MUST · Digital Credentials Query Language query: which credentials and claims the Verifier asks for. · "The DCQL query and response MUST be used as defined in Section 6 of [OIDF.OID4VP]."
      credentials: { // MUST · List of requested credentials, each with format, type constraints and claims. · "credentials: REQUIRED. A non-empty array of Credential Queries as defined in Section 6.1 that specify the requested Credentials."
        id: string // MUST · Identifier of this credential query; the vp_token returns the matching presentation under the same key. [R10]
        format: string // redirect-same, dc-api, redirect-cross: MUST | redirect-same-mdoc: MUST · Requested credential format, e.g. dc+sd-jwt. [R11] [R12]
        meta: { // MUST · Format-specific constraints, such as the accepted credential types. · "meta: REQUIRED. An object defining additional properties requested by the Verifier that apply to the metadata and validity data of the Credential."
          vct_values: string[] // except redirect-same-mdoc: MUST · Accepted Verifiable Credential Types for an SD-JWT VC. · "vct_values: REQUIRED. A non-empty array of strings that specifies allowed values for the type of the requested Verifiable Credential."
          doctype_value: string // only redirect-same-mdoc: MUST · Accepted mdoc document type (doctype), e.g. eu.europa.ec.eudi.pid.1 for the PID. · "doctype_value: REQUIRED. String that specifies an allowed value for the doctype of the requested Verifiable Credential. It MUST be a valid doctype identifier as defined in [ISO.18013-5]."
        }
        claims?: { // MAY · Claims the Verifier wants disclosed. · "claims: OPTIONAL. A non-empty array of objects as defined in Section 6.3 that specifies claims in the requested Credential."
          path: string[] // MUST · Path to the claim inside the credential, as an array of keys. · "path: REQUIRED The value MUST be a non-empty array representing a claims path pointer that specifies the path to a claim within the Credential, as defined in Section 7." · "A claims path pointer MUST be a non-empty array of strings, nulls and non-negative integers."
          intent_to_retain?: boolean // only redirect-same-mdoc: MAY · Tells the Wallet whether the Verifier intends to keep the data element after the transaction (IntentToRetain of ISO/IEC 18013-5). · "intent_to_retain OPTIONAL. A boolean that is equivalent to IntentToRetain variable defined in Section 8.3.2.1.2.1 of [ISO.18013-5]."
        }[]
        trusted_authorities?: { // only dc-api, redirect-same-mdoc: MAY; Wallet: MUST · Which issuers or trust frameworks the Verifier accepts for this credential. · "trusted_authorities: OPTIONAL. A non-empty array of objects as defined in Section 6.1.1 that specifies expected authorities or trust frameworks that certify Issuers, that the Verifier will accept." · "The Authority Key Identifier (aki)-based Trusted Authority Query (trusted_authorities) for DCQL, as defined in section 6.1.1.1 of [OIDF.OID4VP], MUST be supported."
          type?: string // only dc-api, redirect-same-mdoc: MUST when the Verifier uses a trusted authorities query · Kind of trust information in values, e.g. etsi_tl for a Trusted List or aki for an Authority Key Identifier. · "OIDFVP-HAIP-COMMON-REQ-RO-17: The Authority Key Identifier shall use the ETSI trusted Lists (specified in ETSI TS 119 612 [12]) mechanism ("etsi_tl" type)."
          values: string[] // only dc-api, redirect-same-mdoc: MUST · Identifiers of the accepted authorities or trust frameworks, read according to type. · "values: REQUIRED. A non-empty array of strings, where each string (value) contains information specific to the used Trusted Authorities Query type that allows the identification of an issuer, a trust framework, or a federation that an issuer belongs to."
        }[]
      }[]
    }
    client_metadata: { // MUST · Verifier metadata passed inline: response encryption keys and supported formats. · "OIDFVP-HAIP-COMMON-REQ-RO-18: The RO JWT body shall contain the client_metadata parameter."
      jwks: { // MUST · Public keys the Wallet encrypts the Authorization Response to. [R13]
        keys: { // MUST [R13]
          kty: string // MUST · Key type of the JWK, e.g. EC for elliptic curve keys. [R14]
          crv: string // MUST · Elliptic curve of the key, e.g. P-256. [R15]
          x: string // MUST · x coordinate of the EC public key, base64url encoded. [R16]
          y: string // MUST · y coordinate of the EC public key, base64url encoded. [R17]
          kid: string // MUST · Key ID of a response encryption key; it identifies the key within the request. [R18] · "OIDFVP-HAIP-COMMON-REQ-RO-21: The kid parameters shall univocally identify one key."
          use: string // MUST · Intended use of a response encryption key (enc). [R18]
          alg: string // MUST · Key agreement algorithm of a response encryption key; the Wallet uses it as the JWE alg. · "The alg parameter MUST be present in the JWKs. The JWE alg algorithm used MUST be equal to the alg value of the chosen jwk."
        }[]
      }
      vp_formats_supported?: { // except dc-api: MUST when the Wallet cannot obtain the Verifier's supported formats by another mechanism · Credential formats and algorithms the Verifier can process. · "vp_formats_supported: REQUIRED when not available to the Wallet via another mechanism."
        "dc+sd-jwt": { // only redirect-same, redirect-cross: MUST · Credential Format Identifier of SD-JWT VC as the key in vp_formats_supported; its value holds the SD-JWT VC parameters. [R11]
          "sd-jwt_alg_values"?: string[] // only redirect-same, redirect-cross: MAY · Signature algorithms accepted for the issuer-signed SD-JWT. · "sd-jwt_alg_values: OPTIONAL. A non-empty array containing fully-specified identifiers of cryptographic algorithms … supported for an Issuer-signed JWT of an SD-JWT."
          "kb-jwt_alg_values"?: string[] // only redirect-same, redirect-cross: MAY · Signature algorithms accepted for the Key Binding JWT. · "kb-jwt_alg_values: OPTIONAL. A non-empty array containing fully-specified identifiers of cryptographic algorithms … supported for a Key Binding JWT (KB-JWT)."
        }
        mso_mdoc: { // only redirect-same-mdoc: MUST · Credential Format Identifier of ISO mdoc as the key in vp_formats_supported; its value holds the mdoc algorithm parameters. [R12]
          issuerauth_alg_values?: number[] // only redirect-same-mdoc: MAY · COSE algorithms the Verifier accepts for the issuer's signature over the Mobile Security Object (-7 = ES256). · "issuerauth_alg_values: OPTIONAL. A non-empty array containing cryptographic algorithm identifiers. The Credential MUST be considered to fulfill the requirement(s) expressed in this parameter if one of the following is true: 1) The value in the array matches the 'alg' value in the IssuerAuth COSE header."
          deviceauth_alg_values?: number[] // only redirect-same-mdoc: MAY · COSE algorithms the Verifier accepts for the device signature or MAC over the SessionTranscript. · "deviceauth_alg_values: OPTIONAL. A non-empty array containing cryptographic algorithm identifiers. The Credential MUST be considered to fulfill the requirement(s) expressed in this parameter if one of the following is true: 1) The value in the array matches the 'alg' value in the DeviceSignature or DeviceMac COSE header."
        }
      }
      encrypted_response_enc_values_supported: string[] // MUST · Content encryption algorithms the Verifier accepts for the encrypted response, e.g. A128GCM. · "The d-you verifier lists only A128GCM in encrypted_response_enc_values_supported; A256GCM is not offered."
    }
    verifier_info: { // MUST · Array of attestations about the Verifier, e.g. its registration certificate, shown to the Wallet. · "OIDFVP-HAIP-COMMON-REQ-RO-01: The RO JWT body shall contain the verifier_info parameter."
      format: string // MUST · Format of the verifier_info element, e.g. registration_cert. · "The value of the format member of the element in the verifier_info array enclosing the registration certificate shall be: "registration_cert"."
      data: string // MUST · Content of the verifier_info element in the format named by format. · "The value of the data member of the element in the verifier_info array enclosing the registration certificate shall be the base64url encoding of the serialized RP registration certificate."
    }[]
    expected_origins: string[] // only dc-api: MUST; Wallet: MUST · Web origins the request may come from over the Digital Credentials API; the Wallet compares them with the actual origin. · "expected_origins: REQUIRED when signed requests defined in Appendix A.3.2 are used with the Digital Credentials API (DC API)." · "The Wallet MUST compare values in this parameter to the Origin to detect replay of the request from a malicious Verifier. If the Origin does not match any of the entries in expected_origins, the Wallet MUST return an error."
  }
}
// also:
//   - verifier_info element carrying the registration certificate: Verifier: MUST · verifier_info element carrying the relying party's registration certificate. · "OIDFVP-HAIP-COMMON-REQ-RO-13: One of the elements of the verifier_info parameter shall include the registration certificate."
//   - credential_ids in the registration certificate element: Verifier: MUST NOT · The OpenID4VP member that limits a verifier_info element to some of the requested Credentials; the element carrying the registration certificate must not have it. · "OIDFVP-HAIP-COMMON-REQ-RO-14: The element in the verifier_info array enclosing the registration certificate shall be a JSON Object which shall not contain the credential_ids member."
//   - verifier_info element carrying RP Registrar-provided data: no rule · verifier_info element carrying data the relying party registrar provides about the Verifier.
//   - iat (JOSE header): Verifier: MAY · Issuance time placed in the JWS protected header. · "The d-you verifier does not put iat into the JWS Protected Header of the Request Object; the issuance time is only carried in the iat claim of the Request Object body."

